CREATE TABLE IF NOT EXISTS organizations (id text PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (id text PRIMARY KEY, organization_id text NOT NULL REFERENCES organizations(id), email text NOT NULL UNIQUE, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (code text PRIMARY KEY, label text NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id text NOT NULL REFERENCES profiles(id), role_code text NOT NULL REFERENCES roles(code), PRIMARY KEY(user_id,role_code));
CREATE TABLE IF NOT EXISTS sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES profiles(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS units (code text PRIMARY KEY, label text NOT NULL, whole_only boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS suppliers (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, contact text, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, address text NOT NULL, contact text, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS materials (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL CHECK(category IN ('raw','component','packaging','label','other')), unit_code text NOT NULL REFERENCES units(code), requires_inspection boolean NOT NULL DEFAULT true, requires_expiry boolean NOT NULL DEFAULT false, storage_conditions text, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, variant text, unit_code text NOT NULL REFERENCES units(code), expiry_rule text, storage_conditions text, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS warehouses (id text PRIMARY KEY, code text NOT NULL UNIQUE, name text NOT NULL, kind text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS locations (id text PRIMARY KEY, warehouse_id text NOT NULL REFERENCES warehouses(id), code text NOT NULL, name text NOT NULL, UNIQUE(warehouse_id,code));
CREATE TABLE IF NOT EXISTS receipts (id text PRIMARY KEY, code text NOT NULL UNIQUE, supplier_id text NOT NULL REFERENCES suppliers(id), delivery_document text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL CHECK(status IN ('draft','confirmed')), created_by text NOT NULL REFERENCES profiles(id), confirmed_by text REFERENCES profiles(id), confirmed_at timestamptz, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS receipt_items (id text PRIMARY KEY, receipt_id text NOT NULL REFERENCES receipts(id), material_id text NOT NULL REFERENCES materials(id), supplier_lot_number text NOT NULL, quantity numeric(18,6) NOT NULL CHECK(quantity>0), manufactured_at date, expires_at date, lot_id text UNIQUE);
CREATE TABLE IF NOT EXISTS lots (id text PRIMARY KEY, code text NOT NULL UNIQUE, kind text NOT NULL CHECK(kind IN ('material','finished')), material_id text REFERENCES materials(id), product_id text REFERENCES products(id), supplier_id text REFERENCES suppliers(id), supplier_lot_number text, parent_lot_id text REFERENCES lots(id), receipt_item_id text UNIQUE REFERENCES receipt_items(id), production_run_id text UNIQUE, manufactured_at date, expires_at date, expiry_basis text, quality_status text NOT NULL DEFAULT 'quarantine' CHECK(quality_status IN ('quarantine','released','rejected')), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, public_token text NOT NULL UNIQUE, CHECK ((kind='material' AND material_id IS NOT NULL AND product_id IS NULL) OR (kind='finished' AND product_id IS NOT NULL AND material_id IS NULL)));
CREATE TABLE IF NOT EXISTS specifications (id text PRIMARY KEY, product_id text NOT NULL REFERENCES products(id), code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE IF NOT EXISTS specification_versions (id text PRIMARY KEY, specification_id text NOT NULL REFERENCES specifications(id), version_no integer NOT NULL, status text NOT NULL CHECK(status IN ('draft','review','active','archived')), base_quantity numeric(18,6) NOT NULL CHECK(base_quantity>0), unit_code text NOT NULL REFERENCES units(code), route_snapshot jsonb NOT NULL DEFAULT '[]', approved_by text REFERENCES profiles(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(specification_id,version_no));
CREATE TABLE IF NOT EXISTS specification_items (id text PRIMARY KEY, version_id text NOT NULL REFERENCES specification_versions(id), material_id text NOT NULL REFERENCES materials(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0), unit_code text NOT NULL REFERENCES units(code), tolerance_percent numeric(8,3), UNIQUE(version_id,material_id));
CREATE TABLE IF NOT EXISTS process_templates (id text PRIMARY KEY, name text NOT NULL, version_no integer NOT NULL, status text NOT NULL);
CREATE TABLE IF NOT EXISTS process_template_steps (id text PRIMARY KEY, template_id text NOT NULL REFERENCES process_templates(id), sequence_no integer NOT NULL, name text NOT NULL, required boolean NOT NULL DEFAULT true, field_schema jsonb NOT NULL DEFAULT '{}', UNIQUE(template_id,sequence_no));
CREATE TABLE IF NOT EXISTS quality_plan_versions (id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('incoming','finished')), subject_id text NOT NULL, version_no integer NOT NULL, status text NOT NULL, checks jsonb NOT NULL DEFAULT '[]', approved_at timestamptz, UNIQUE(kind,subject_id,version_no));
CREATE TABLE IF NOT EXISTS production_orders (id text PRIMARY KEY, code text NOT NULL UNIQUE, product_id text NOT NULL REFERENCES products(id), spec_version_id text NOT NULL REFERENCES specification_versions(id), planned_quantity numeric(18,6) NOT NULL CHECK(planned_quantity>0), line text NOT NULL, assigned_to text REFERENCES profiles(id), status text NOT NULL CHECK(status IN ('draft','planned','reserved','in_progress','paused','production_complete','closed','cancelled')), planned_date date, created_by text NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS production_runs (id text PRIMARY KEY, order_id text NOT NULL REFERENCES production_orders(id), code text NOT NULL UNIQUE, status text NOT NULL CHECK(status IN ('in_progress','completed')), started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_by text NOT NULL REFERENCES profiles(id));
CREATE TABLE IF NOT EXISTS material_reservations (id text PRIMARY KEY, order_id text NOT NULL REFERENCES production_orders(id), lot_id text NOT NULL REFERENCES lots(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0), consumed_quantity numeric(18,6) NOT NULL DEFAULT 0 CHECK(consumed_quantity>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,lot_id));
CREATE TABLE IF NOT EXISTS material_consumptions (id text PRIMARY KEY, run_id text NOT NULL REFERENCES production_runs(id), order_id text NOT NULL REFERENCES production_orders(id), lot_id text NOT NULL REFERENCES lots(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0), unit_code text NOT NULL REFERENCES units(code), actor_id text NOT NULL REFERENCES profiles(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS production_step_records (id text PRIMARY KEY, run_id text NOT NULL REFERENCES production_runs(id), sequence_no integer NOT NULL, name text NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz NOT NULL DEFAULT now(), result jsonb NOT NULL DEFAULT '{}', equipment text, comment text, actor_id text NOT NULL REFERENCES profiles(id), UNIQUE(run_id,sequence_no));
CREATE TABLE IF NOT EXISTS finished_lots (lot_id text PRIMARY KEY REFERENCES lots(id), run_id text NOT NULL UNIQUE REFERENCES production_runs(id), order_id text NOT NULL REFERENCES production_orders(id), spec_version_id text NOT NULL REFERENCES specification_versions(id), manufactured_quantity numeric(18,6) NOT NULL CHECK(manufactured_quantity>0), scrap_quantity numeric(18,6) NOT NULL DEFAULT 0 CHECK(scrap_quantity>=0), quarantine_quantity numeric(18,6) NOT NULL CHECK(quarantine_quantity>0), CHECK(manufactured_quantity=quarantine_quantity+scrap_quantity));
CREATE TABLE IF NOT EXISTS quality_checks (id text PRIMARY KEY, lot_id text NOT NULL REFERENCES lots(id), plan_version_id text REFERENCES quality_plan_versions(id), kind text NOT NULL CHECK(kind IN ('incoming','finished')), attempt integer NOT NULL, status text NOT NULL CHECK(status IN ('submitted','additional_requested')), result_summary text NOT NULL, passed boolean NOT NULL, performed_by text NOT NULL REFERENCES profiles(id), performed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lot_id,kind,attempt));
CREATE TABLE IF NOT EXISTS quality_check_results (id text PRIMARY KEY, check_id text NOT NULL REFERENCES quality_checks(id), item_key text NOT NULL, value_text text NOT NULL, passed boolean NOT NULL, UNIQUE(check_id,item_key));
CREATE TABLE IF NOT EXISTS quality_decisions (id text PRIMARY KEY, lot_id text NOT NULL REFERENCES lots(id), check_id text REFERENCES quality_checks(id), decision text NOT NULL CHECK(decision IN ('release','reject','additional')), basis text NOT NULL, actor_id text NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lot_holds (id text PRIMARY KEY, lot_id text NOT NULL REFERENCES lots(id), reason text NOT NULL, source_lot_id text REFERENCES lots(id), protective boolean NOT NULL DEFAULT false, placed_by text NOT NULL REFERENCES profiles(id), placed_at timestamptz NOT NULL DEFAULT now(), released_by text REFERENCES profiles(id), released_at timestamptz, release_reason text);
CREATE TABLE IF NOT EXISTS inventory_movements (id text PRIMARY KEY, lot_id text NOT NULL REFERENCES lots(id), movement_type text NOT NULL, quantity numeric(18,6) NOT NULL CHECK(quantity>0), unit_code text NOT NULL REFERENCES units(code), from_warehouse_id text REFERENCES warehouses(id), to_warehouse_id text REFERENCES warehouses(id), basis_type text NOT NULL, basis_id text NOT NULL, reversal_of text REFERENCES inventory_movements(id), actor_id text NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(from_warehouse_id IS NOT NULL OR to_warehouse_id IS NOT NULL), CHECK(from_warehouse_id IS DISTINCT FROM to_warehouse_id));
CREATE TABLE IF NOT EXISTS shipments (id text PRIMARY KEY, code text NOT NULL UNIQUE, customer_id text NOT NULL REFERENCES customers(id), customer_name_snapshot text, address_snapshot text NOT NULL, customer_order text, ship_date date, status text NOT NULL CHECK(status IN ('draft','picking','ready','shipped','cancelled')), created_by text NOT NULL REFERENCES profiles(id), confirmed_by text REFERENCES profiles(id), confirmed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS shipment_items (id text PRIMARY KEY, shipment_id text NOT NULL REFERENCES shipments(id), product_id text NOT NULL REFERENCES products(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS shipment_lot_allocations (id text PRIMARY KEY, shipment_item_id text NOT NULL REFERENCES shipment_items(id), lot_id text NOT NULL REFERENCES lots(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0), UNIQUE(shipment_item_id,lot_id));
CREATE TABLE IF NOT EXISTS customer_returns (id text PRIMARY KEY, shipment_id text NOT NULL REFERENCES shipments(id), code text NOT NULL UNIQUE, reason text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL REFERENCES profiles(id));
CREATE TABLE IF NOT EXISTS return_items (id text PRIMARY KEY, return_id text NOT NULL REFERENCES customer_returns(id), lot_id text NOT NULL REFERENCES lots(id), quantity numeric(18,6) NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS nonconformities (id text PRIMARY KEY, code text NOT NULL UNIQUE, source_type text NOT NULL, source_id text, lot_id text REFERENCES lots(id), description text NOT NULL, category text NOT NULL DEFAULT 'quality', severity text NOT NULL DEFAULT 'medium', status text NOT NULL DEFAULT 'open', owner_id text REFERENCES profiles(id), resolution text, due_date date, created_at timestamptz NOT NULL DEFAULT now(), created_by text NOT NULL REFERENCES profiles(id));
CREATE TABLE IF NOT EXISTS recall_campaigns (id text PRIMARY KEY, code text NOT NULL UNIQUE, source_lot_id text NOT NULL REFERENCES lots(id), reason text NOT NULL, action_plan text NOT NULL, status text NOT NULL CHECK(status IN ('open','closed')), owner_id text NOT NULL REFERENCES profiles(id), final_decision text, unresolved_explanation text, created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE IF NOT EXISTS recall_affected_lots (recall_id text NOT NULL REFERENCES recall_campaigns(id), lot_id text NOT NULL REFERENCES lots(id), PRIMARY KEY(recall_id,lot_id));
CREATE TABLE IF NOT EXISTS recall_customer_actions (id text PRIMARY KEY, recall_id text NOT NULL REFERENCES recall_campaigns(id), shipment_id text NOT NULL REFERENCES shipments(id), lot_id text NOT NULL REFERENCES lots(id), status text NOT NULL CHECK(status IN ('pending','notified','confirmed','returned','resolved')), note text, notified_at timestamptz, confirmed_quantity numeric(18,6) NOT NULL DEFAULT 0, returned_quantity numeric(18,6) NOT NULL DEFAULT 0, actor_id text NOT NULL REFERENCES profiles(id), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(recall_id,shipment_id,lot_id));
CREATE TABLE IF NOT EXISTS documents (id text PRIMARY KEY, title text NOT NULL, kind text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, created_by text NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_versions (id text PRIMARY KEY, document_id text NOT NULL REFERENCES documents(id), version_no integer NOT NULL, storage_path text, mime_type text, size_bytes bigint, snapshot jsonb, created_by text NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(document_id,version_no));
CREATE TABLE IF NOT EXISTS attachments (id text PRIMARY KEY, document_version_id text NOT NULL REFERENCES document_versions(id), name text NOT NULL, storage_path text NOT NULL, mime_type text NOT NULL, size_bytes bigint NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES profiles(id), title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS status_history (id text PRIMARY KEY, entity_type text NOT NULL, entity_id text NOT NULL, old_status text, new_status text NOT NULL, actor_id text NOT NULL REFERENCES profiles(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id text PRIMARY KEY, entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, old_value jsonb, new_value jsonb, actor_id text NOT NULL REFERENCES profiles(id), reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, actor_id text NOT NULL REFERENCES profiles(id), action text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_movements_lot ON inventory_movements(lot_id);
CREATE INDEX IF NOT EXISTS idx_consumptions_lot ON material_consumptions(lot_id);
CREATE INDEX IF NOT EXISTS idx_consumptions_run ON material_consumptions(run_id);
CREATE INDEX IF NOT EXISTS idx_ship_alloc_lot ON shipment_lot_allocations(lot_id);
CREATE INDEX IF NOT EXISTS idx_holds_active ON lot_holds(lot_id) WHERE released_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_audit_time ON audit_logs(created_at DESC);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='receipt_items_lot_fk') THEN
    ALTER TABLE receipt_items ADD CONSTRAINT receipt_items_lot_fk FOREIGN KEY(lot_id) REFERENCES lots(id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='lots_production_run_fk') THEN
    ALTER TABLE lots ADD CONSTRAINT lots_production_run_fk FOREIGN KEY(production_run_id) REFERENCES production_runs(id);
  END IF;
END $$;
CREATE OR REPLACE FUNCTION medtrace_guard_spec_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' AND OLD.status IN ('active','archived') THEN RAISE EXCEPTION 'Approved specification versions are immutable'; END IF;
  IF TG_OP='UPDATE' AND OLD.status IN ('active','archived') THEN
    IF NEW.specification_id<>OLD.specification_id OR NEW.version_no<>OLD.version_no OR NEW.base_quantity<>OLD.base_quantity OR NEW.unit_code<>OLD.unit_code OR NEW.route_snapshot<>OLD.route_snapshot OR NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NOT (OLD.status='active' AND NEW.status='archived') THEN
      RAISE EXCEPTION 'Approved specification versions are immutable';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
DROP TRIGGER IF EXISTS trg_spec_version_immutable ON specification_versions;
CREATE TRIGGER trg_spec_version_immutable BEFORE UPDATE OR DELETE ON specification_versions FOR EACH ROW EXECUTE FUNCTION medtrace_guard_spec_version();
CREATE OR REPLACE FUNCTION medtrace_guard_spec_item() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_status text;
BEGIN
  SELECT status INTO v_status FROM specification_versions WHERE id=COALESCE(NEW.version_id,OLD.version_id);
  IF v_status IN ('active','archived') THEN RAISE EXCEPTION 'Approved specification items are immutable'; END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
DROP TRIGGER IF EXISTS trg_spec_item_immutable ON specification_items;
CREATE TRIGGER trg_spec_item_immutable BEFORE UPDATE OR DELETE ON specification_items FOR EACH ROW EXECUTE FUNCTION medtrace_guard_spec_item();
CREATE OR REPLACE FUNCTION medtrace_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Confirmed records are append-only'; END $$;
DROP TRIGGER IF EXISTS trg_movements_append_only ON inventory_movements;
CREATE TRIGGER trg_movements_append_only BEFORE UPDATE OR DELETE ON inventory_movements FOR EACH ROW EXECUTE FUNCTION medtrace_append_only();
DROP TRIGGER IF EXISTS trg_audit_append_only ON audit_logs;
CREATE TRIGGER trg_audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION medtrace_append_only();
